using System;using System.IO;using System.Linq;using System.Threading;using System.Threading.Tasks;using System.Diagnostics;using System.Collections.Concurrent;using Musikbox;
class Voice64 {
 static int count;static void Check(bool ok,string why){if(!ok)throw new Exception(why);count++;Console.WriteLine("PASS "+why);}static async Task Wait(Func<bool> ready){var t=Stopwatch.StartNew();while(!ready()){if(t.ElapsedMilliseconds>4000)throw new Exception("Zeitlimit");await Task.Delay(10);}}
 sealed class Input:IVoiceInput{public event Action<byte[],int> DataAvailable;public event Action<Exception> Stopped;public bool Started,Disposed;public int DisposeDelay,StartDelay;public void Start(){if(StartDelay>0)Thread.Sleep(StartDelay);Started=true;}public void Dispose(){if(DisposeDelay>0)Thread.Sleep(DisposeDelay);Disposed=true;Stopped?.Invoke(null);}public void Clip(){var speech=new byte[3200];for(int i=1;i<speech.Length;i+=2)speech[i]=0x10;var quiet=new byte[3200];for(int i=0;i<3;i++)DataAvailable?.Invoke(speech,speech.Length);for(int i=0;i<8;i++)DataAvailable?.Invoke(quiet,quiet.Length);}}
 static ProcessStartInfo Command(bool slow){var start=new ProcessStartInfo{FileName=OperatingSystem.IsWindows()?"cmd.exe":"/bin/sh"};if(OperatingSystem.IsWindows()){start.ArgumentList.Add("/d");start.ArgumentList.Add("/c");start.ArgumentList.Add(slow?"ping -n 21 127.0.0.1 >nul":"echo erkannt");}else{start.ArgumentList.Add("-c");start.ArgumentList.Add(slow?"sleep 20":"printf erkannt");}return start;}
 static async Task Main(){var inputs=new ConcurrentQueue<Input>();int recognized=0;var texts=new ConcurrentQueue<string>();using(var service=new VoiceService(()=>{var i=new Input();inputs.Enqueue(i);return i;},async(p,q,t)=>{await Task.Delay(20,t);return "Lainey Wilson";},false)){service.RecognitionCompleted+=(g,a)=>{Interlocked.Increment(ref recognized);texts.Enqueue(a[0]);};await service.Start(new[]{new Song{Artist="Lainey Wilson"}});inputs.TryPeek(out var input);Check(service.Active&&input.Started,"Aufnahme startet");input.Clip();await Wait(()=>recognized==1);await Wait(()=>!service.Active);Check(texts.All(t=>t=="Lainey Wilson"),"Ergebnis wird geliefert und Mikrofon automatisch beendet");await Wait(()=>input.Disposed);Check(input.Disposed,"Aufnahmegerät wird freigegeben");await service.Start(new[]{new Song{Artist="Lainey Wilson"}});Check(service.Active,"Mikrofon kann für nächste Suche erneut gestartet werden");inputs.TryPeek(out var previous);var next=inputs.ToArray().Last();next.Clip();await Wait(()=>recognized==2);await Wait(()=>!service.Active);Check(texts.All(t=>t=="Lainey Wilson"),"Zweite Erkennung nach Neustart");int before=service.Generation;service.Stop();Check(!service.Active&&service.Generation>before,"X beendet Aufnahme und wechselt Generation");}
 using(var slow=new VoiceService(()=>new Input{StartDelay=700},(p,q,t)=>Task.FromResult(""),false,TimeSpan.FromMilliseconds(100))){int failures=0;slow.ErrorUpdated+=(g,message)=>failures++;var clock=Stopwatch.StartNew();await slow.Start(Array.Empty<Song>());Check(clock.ElapsedMilliseconds<500&&!slow.Active&&failures==1,"Blockierter Gerätestart endet mit sichtbarem Fehler statt Dauerzustand");}
 var blocked=new TaskCompletionSource<string>(TaskCreationOptions.RunContinuationsAsynchronously);var entered=new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);var recordings=new ConcurrentQueue<Input>();int calls=0,results=0;CancellationToken oldToken=default;
 using(var service=new VoiceService(()=>{var i=new Input{DisposeDelay=600};recordings.Enqueue(i);return i;},(p,q,t)=>{int n=Interlocked.Increment(ref calls);if(n==1){oldToken=t;entered.TrySetResult(true);return blocked.Task;}return Task.FromResult("Neu");},false)){service.RecognitionCompleted+=(g,a)=>Interlocked.Increment(ref results);await service.Start(Array.Empty<Song>());recordings.TryPeek(out var first);first.Clip();await entered.Task;var timer=Stopwatch.StartNew();service.Stop();timer.Stop();Check(timer.ElapsedMilliseconds<150,"Abbruch wartet nicht auf Erkennung oder Geräte-Dispose");Check(oldToken.IsCancellationRequested&&!service.Active,"Laufende Erkennung erhält Abbruchsignal");await service.Start(Array.Empty<Song>());Check(service.Active,"Sofortiger Neustart trotz alter Hintergrundarbeit");blocked.SetResult("Verspätet");await Task.Delay(100);Check(results==0,"Verspäteter Text wird verworfen");var second=recordings.ToArray()[1];second.Clip();await Wait(()=>results==1);await Task.Delay(650);Check(!service.Active&&results==1,"Neue Aufnahme liefert Ergebnis und beendet sich; alte Geräte-Abschlussmeldung stört nicht");service.Stop();}
 int errors=0;using(var service=new VoiceService(()=>new Input(),(p,q,t)=>Task.FromException<string>(new IOException("Enginefehler")),false)){service.ErrorUpdated+=(g,m)=>Interlocked.Increment(ref errors);await service.Start(Array.Empty<Song>());var f=typeof(VoiceService).GetField("current",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(service);var i=(Input)f.GetType().GetField("Input").GetValue(f);i.Clip();await Wait(()=>errors==1);Check(!service.Active,"Enginefehler lässt Mikrofon erneut startbar zurück");}
 using(var cancel=new CancellationTokenSource()){var start=Command(true);var running=CancellableProcess.RunAsync(start,cancel.Token,TimeSpan.FromSeconds(25));await Task.Delay(150);var timer=Stopwatch.StartNew();cancel.Cancel();bool stopped=false;try{await running;}catch(OperationCanceledException){stopped=true;}Check(stopped&&timer.ElapsedMilliseconds<2000,"Echter Unterprozess einschließlich Kindprozess wird abgebrochen");}
 {var start=Command(true);bool timeout=false;try{await CancellableProcess.RunAsync(start,CancellationToken.None,TimeSpan.FromMilliseconds(200));}catch(TimeoutException){timeout=true;}Check(timeout,"Hängender Prozess wird durch Zeitlimit beendet");}
 {var start=Command(false);Check((await CancellableProcess.RunAsync(start,CancellationToken.None,TimeSpan.FromSeconds(2))).Trim()=="erkannt","Prozessausgabe wird vollständig eingelesen");}
 Console.WriteLine("BESTANDEN: "+count+" Sprachsitzungs-/Prozessprüfungen; keine physische Mikrofonaufnahme.");}
}
